import{_ as t,o as a,c as n,ak as i}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy current project baseline","description":"Updated October 23, 2026 from direct owner decisions. Sherwin owns project/design decisions; Christian owns technical implementation.","frontmatter":{"title":"Chainy current project baseline","description":"Updated October 23, 2026 from direct owner decisions. Sherwin owns project/design decisions; Christian owns technical implementation.","source":"docs/project-baseline.md","category":"Start here","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/project-baseline.md","filePath":"content/docs/project-baseline.md"}'),r={name:"content/docs/project-baseline.md"};function o(d,e,s,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-current-project-baseline">Chainy current project baseline<a class="header-anchor" href="#chainy-current-project-baseline" aria-label="Link to this section">​</a></h1><p>Updated October 23, 2026 from direct owner decisions. Sherwin owns project/design decisions; Christian owns technical implementation.</p><p><strong>Capstone title:</strong> Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain &amp; AI)</p><h2 id="governing-mission-and-scope">Governing mission and scope<a class="header-anchor" href="#governing-mission-and-scope" aria-label="Link to this section">​</a></h2><p>Build an offline Unity/C# Android learning adventure for ages 12–17, initially in English, accessible in communities with limited connectivity. <a href="/Chainy-Docs/content/docs/game-design.html">GDD v2</a> is now the canonical gameplay source. It supersedes the October 12 mini-game-first scope, not the usable infrastructure in <a href="/Chainy-Docs/content/docs/technical-design.html">Christian&#39;s technical design</a>.</p><p>The full experience restores Web3, Blockchain and AI island services in sequence. A single fictional lantern purchase connects economic actions, record repair and later AI judgment. All twelve concepts remain in the full design. No real cryptocurrency, wallet, payment, public blockchain or cloud AI is required.</p><h2 id="confirmed-decisions">Confirmed decisions<a class="header-anchor" href="#confirmed-decisions" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Decision</th><th>Current position</th></tr></thead><tbody><tr><td>Adoption</td><td>V2 adopted October 23, including standalone Wordle and BlockMatch deferrals</td></tr><tr><td>Beta</td><td><strong>November 10, 2026 — Cryptita Plays community beta testing</strong>; replaces the Tambunan NHS / Marinduque event</td></tr><tr><td>Pre-final</td><td><strong>November 21, 2026</strong>; unchanged</td></tr><tr><td>CORE</td><td>W01–W04, B01–B03 and demo B07, contextual Quiz, compact exploration/dialogue/UI, quest log/encyclopedia and dependable SQLite saves</td></tr><tr><td>STRETCH</td><td>A01–A03 actual tiny offline classifier, only after core Android checks pass</td></tr><tr><td>FULL</td><td>W05–W08, B04–B06/full B07, A04–A05, standalone Wordle and BlockMatch; no beta commitment</td></tr><tr><td>LATER SERVICE</td><td>Personal learner phones, teacher vouchers/activation, offline pairing/dashboard, collection/upload and distribution; not a beta dependency</td></tr><tr><td>Storage</td><td>SQLite locally; persist related balances, inventory, ledger and quest changes atomically. JSON may be an export format.</td></tr><tr><td>Profile</td><td>Beta local demo profile; a learner code does not authenticate identity or restore another phone</td></tr><tr><td>Visuals</td><td>Existing fixed orthographic isometric, restrained low-poly direction retained; blue-haired yellow-clad Explorer and screen-faced robot identity</td></tr><tr><td>Dialogue</td><td>Existing live-world overlay retained: bottom dialogue, middle choices, left/right portraits, world input disabled</td></tr><tr><td>Guides</td><td>Sean (Web3), Matthew (Blockchain), Lee (AI); reuse robot base</td></tr><tr><td>Ownership</td><td>Sherwin: decisions/coordination; Christian: code/data/builds/integration; Luis: art; Sean: all authored project docs; Miguel: UI</td></tr><tr><td>Management</td><td>Edit through the team board with individual named history; GitHub issues are queued copies; backlog.json is a publication snapshot. Trello is retired.</td></tr></tbody></table><p>Adoption defines intended scope, not tested implementation or school approval. Preserve completed work and human task ownership; do not reset status because requirements changed.</p><h2 id="current-implementation-evidence">Current implementation evidence<a class="header-anchor" href="#current-implementation-evidence" aria-label="Link to this section">​</a></h2><p>The October 12 supplied source reports movement completed, SQLite/profile/Quiz/UI/models in progress, and Wordle/BlockMatch not started. The October 22 v2 input reports movement and dialogue playable. These are reports, not independently passed Android tests.</p><p>The live board contains individual updates that take precedence over older local snapshots. Record build revision, device, expected/actual outcome and evidence before claiming acceptance. No new gameplay code or database migration is authorized by this documentation reconciliation.</p><h2 id="delivery-boundary">Delivery boundary<a class="header-anchor" href="#delivery-boundary" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Window</th><th>Planning target / fixed event</th></tr></thead><tbody><tr><td>Oct 23–24</td><td>Confirm source, build and persistent core contract; first Android checkpoint</td></tr><tr><td>Oct 25–28</td><td>W01–W04 vertical slice and supporting UI/art/copy</td></tr><tr><td>Oct 29–30</td><td>B01–B03/demo B07; scope freeze</td></tr><tr><td>Oct 31–Nov 6</td><td>Integration, named-device tests, offline/recovery checks and instructions</td></tr><tr><td>Nov 7–9</td><td>Blocker fixes, regression, beta rehearsal and candidate freeze</td></tr><tr><td><strong>Nov 10</strong></td><td><strong>Cryptita Plays community beta testing</strong></td></tr><tr><td>Nov 11–13</td><td>Actual findings, retested fixes and evidence analysis</td></tr><tr><td>Nov 14–16</td><td>Manuscript and evidence package</td></tr><tr><td>Nov 17–20</td><td>Defense rehearsal, recovery drill and release freeze</td></tr><tr><td><strong>Nov 21</strong></td><td><strong>Pre-final</strong></td></tr></tbody></table><p>Internal dates are targets, not guaranteed capacity or proof that past deadlines were met. The GDD estimates 95–153 focused core hours plus 20–35 for optional AI; these are estimates, not measured work. Reported 16–18-hour daily availability is not a sustainable productivity assumption. Protect integration, QA, manuscript and rehearsal time. A moved beta does not automatically add features.</p><h2 id="school-requirements">School requirements<a class="header-anchor" href="#school-requirements" aria-label="Link to this section">​</a></h2><p>The documented pre-final expectation includes functional core modules, complete manuscript chapters and required pilot-area evidence/documents. The school’s 60% calculation, eight unnamed quality criteria and “ISO 2010” wording remain unresolved. Do not calculate school completion from task counts.</p><p>Cryptita Plays community testing is the approved project event, not proof that the school accepts it as the study pilot or that participant permissions exist. Sean records adviser/school requirements; Sherwin coordinates community arrangements. No results, approvals or identities may be invented. See the <a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">evidence map</a>.</p><h2 id="device-target">Device target<a class="header-anchor" href="#device-target" aria-label="Link to this section">​</a></h2><p>Retain provisional Android 10+/11+, 4 GB physical RAM, 64 GB total storage, ARM64, OpenGL ES 3.2 or Vulkan 1.1. Android 11+ is the provisional test interpretation; Android 10 remains a compatibility candidate. These are targets, not measured support. See <a href="/Chainy-Docs/content/docs/hardware-validation.html">device checks</a>.</p><h2 id="decisions-still-needed">Decisions still needed<a class="header-anchor" href="#decisions-still-needed" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Item</th><th>Owner / handoff</th><th>Required evidence</th></tr></thead><tbody><tr><td>Implementation</td><td>Christian → Sean</td><td>Actual source revision, Unity version, reproducible Android build and current schema</td></tr><tr><td>Persistence</td><td>Christian → Miguel/Sean</td><td>Transaction/idempotency/checkpoint contract, version handling, profile separation and failure behavior</td></tr><tr><td>Content</td><td>Sherwin → Sean</td><td>Detailed quest copy, contextual Quiz rules and accurate explanations; separate later-mode rules</td></tr><tr><td>AI stretch</td><td>Sherwin + Christian handoff</td><td>Core pass evidence, available capacity, approved feature encoding/data and actual classifier prototype</td></tr><tr><td>Community beta</td><td>Sherwin → Sean</td><td>Reconfirmed participants/devices/arrangements; approved fields, custodian and safe process</td></tr><tr><td>School evidence</td><td>Sean</td><td>Whether community feedback satisfies any pilot requirement; named rubric criteria and completion calculation</td></tr></tbody></table><h2 id="traceable-requirements">Traceable requirements<a class="header-anchor" href="#traceable-requirements" aria-label="Link to this section">​</a></h2><p><a href="/Chainy-Docs/content/docs/requirements/product-requirements.html">V2-R01–12</a> and GDD GP-01–GP-14 govern new acceptance. TD-R and CH-R meanings are preserved in the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/readme.html">adoption archive</a> and earlier archive. The <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">task plan</a> separates core, conditional and deferred work.</p><h2 id="publication-and-tooling">Publication and tooling<a class="header-anchor" href="#publication-and-tooling" aria-label="Link to this section">​</a></h2><p>The <a href="/Chainy-Docs/content/tools/docs-viewer/readme.html">documentation viewer</a> and <a href="/Chainy-Docs/content/docs/team-board-guide.html">team board</a> are online management tools, separate from offline gameplay. Changes to local files do not prove the public viewer or deployed board service has been published. Keep participant data, identity maps, credentials and signing keys out of this repository and public issues.</p></div>',1)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
